    /// <summary>
    /// MPJ_13531_CustReportLogos
    /// </summary>
    /// <param name = "_custInvoiceJour">Invoice journal header</param>
    /// <param name = "_companyInfo">Company info</param>
    protected void populateFreeTextInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
    {
        next populateFreeTextInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);

        // MPJ_13531_CustReportLogos
        Image img = CustTable::metGetCustReportLogo(_custInvoiceJour.InvoiceAccount);
        if(img)
        {
            freeTextInvoiceHeaderFooterTmp.companyLogo = img.getData();
        }
    }
